const input = $input.first().json || {};
let router = input;
try { router = $('Intent Router2').first().json || input; } catch (e) {}
const body = router.body && typeof router.body === 'object' ? router.body : {};
const context = router.region_context && typeof router.region_context === 'object'
  ? router.region_context
  : (body.region_context && typeof body.region_context === 'object' ? body.region_context : {});
const explicitKey = String(router.region_key || body.region_key || context.key || '').trim();
const explicitName = String(router.region_name || body.region_name || context.name || context.city || context.country || '').trim();

function normalizeEntries(value) {
  const source = value && value.regions !== undefined ? value.regions : value;
  const entries = [];
  if (Array.isArray(source)) {
    for (const item of source) {
      if (typeof item === 'string') entries.push({ key: item, name: item });
      else if (item && typeof item === 'object') {
        const key = item.key || item.region_key || item.id || '';
        const name = item.name || item.region_name || item.city || item.country || key;
        if (key || name) entries.push({ ...item, key: key || name, name });
      }
    }
  } else if (source && typeof source === 'object') {
    for (const [key, value] of Object.entries(source)) {
      if (['status', 'count', 'message'].includes(key)) continue;
      entries.push(value && typeof value === 'object'
        ? { ...value, key, name: value.name || value.region_name || value.city || key }
        : { key, name: String(value || key) });
    }
  }
  return entries;
}

const supplied = router.available_regions || body.available_regions || router.asia_regions || body.asia_regions || [];
const entries = normalizeEntries(supplied);
if (explicitKey || explicitName) {
  const exists = entries.some((item) => item.key === explicitKey || item.name === explicitName);
  if (!exists) entries.unshift({
    ...context,
    key: explicitKey || explicitName,
    name: explicitName || explicitKey,
    city: router.city || body.city || context.city || '',
    province: router.province || body.province || context.province || '',
    country: router.country || body.country || context.country || '',
    country_code: router.country_code || body.country_code || context.country_code || '',
    asian_subregion: router.asian_subregion || body.asian_subregion || context.asian_subregion || '',
    latitude: router.latitude ?? body.latitude ?? context.latitude ?? null,
    longitude: router.longitude ?? body.longitude ?? context.longitude ?? null,
    timezone: router.timezone || body.timezone || context.timezone || '',
  });
}

return [{ json: {
  status: 'success',
  scope: 'ASIA',
  count: entries.length,
  regions: entries,
  supported_countries: router.supported_countries || body.supported_countries || [],
  selected_context: context,
} }];

const match = $input.first().json || {};
const body = match.body && typeof match.body === 'object' ? match.body : {};
const context = match.region_context && typeof match.region_context === 'object' ? match.region_context : {};
const merged = { ...match, ...body };
return [{ json: {
  ...merged,
  region_key: match.matched_region_key || merged.region_key || context.key || '',
  region_name: match.matched_region_name || merged.region_name || context.name || context.city || context.country || '',
  city: merged.city || context.city || '',
  province: merged.province || context.province || '',
  country: merged.country || context.country || '',
  country_code: merged.country_code || context.country_code || '',
  asian_subregion: merged.asian_subregion || context.asian_subregion || '',
  latitude: merged.latitude ?? context.latitude ?? null,
  longitude: merged.longitude ?? context.longitude ?? null,
  timezone: merged.timezone || context.timezone || '',
  system_status: merged.system_status || (merged.telemetry ? 'CONTEXT_READY' : 'CONTEXT_PARTIAL'),
  context_source: 'wiaas_asia_selected_region',
} }];

parameters.jsonOutput:
={{ (() => {
  const raw = $json.body && typeof $json.body === 'object' ? { ...$json, ...$json.body } : $json;
  const context = raw.region_context && typeof raw.region_context === 'object' ? raw.region_context : {};
  const climate = raw.climate_matrix || {};
  const ledger = raw.ledger || raw.synthetic_resource_ledger || {};
  const forecast7d = raw.forecast_7d || context.forecast_7d || {};
  const telemetry = raw.telemetry || climate.telemetry || {};
  const region = raw.region_name || raw.monitored_region || context.name || context.city || context.country || 'Selected Asian region';
  const country = raw.country || context.country || '';

  const heatIndex = climate.heat_index_celsius ?? null;
  const vpd = climate.vapor_pressure_deficit_kpa ?? null;
  const gridSurge = ledger.grid_demand_surge_pct ?? null;
  const thermalOverhead = ledger.fuel_thermal_overhead_pct ?? null;
  const evaporationLoss = ledger.water_surface_evap_loss_pct ?? climate.water_surface_evap_loss_pct ?? null;
  const irrigationEfficiency = ledger.water_irrigation_efficiency_pct ?? climate.water_irrigation_efficiency_pct ?? null;
  const windSpeed = telemetry.wind_speed_kmh ?? (telemetry.wind && telemetry.wind.speed_kmh) ?? null;
  const windDir = telemetry.wind_direction_degrees ?? (telemetry.wind && telemetry.wind.direction_degrees) ?? null;

  let riskLevel = String(raw.risk_level || '').toUpperCase();
  let missionScore = Number(raw.mission_criticality_score);
  if (!riskLevel) {
    if ((heatIndex ?? -Infinity) >= 40 || (vpd ?? -Infinity) >= 2.8 || (gridSurge ?? -Infinity) >= 15 || (thermalOverhead ?? -Infinity) >= 10) riskLevel = 'HIGH';
    else if ((heatIndex ?? -Infinity) >= 35 || (vpd ?? -Infinity) >= 2 || (gridSurge ?? -Infinity) >= 8 || (thermalOverhead ?? -Infinity) >= 5) riskLevel = 'MEDIUM';
    else if (Object.keys(telemetry).length || Object.keys(climate).length || Object.keys(ledger).length) riskLevel = 'LOW';
    else riskLevel = 'DATA_PENDING';
  }
  if (!Number.isFinite(missionScore)) missionScore = riskLevel === 'HIGH' ? 85 : (riskLevel === 'MEDIUM' ? 55 : (riskLevel === 'LOW' ? 25 : null));

  const gp = raw.grid_predictions || {};
  const summary = gp.analytics_summary || {};
  const trigger = summary.m2m_trigger || {};
  const state = {
    metadata: {
      region,
      city: raw.city || context.city || '',
      province: raw.province || context.province || '',
      country,
      country_code: raw.country_code || context.country_code || '',
      asian_subregion: raw.asian_subregion || context.asian_subregion || 'Asia',
      latitude: raw.latitude ?? context.latitude ?? null,
      longitude: raw.longitude ?? context.longitude ?? null,
      timezone: raw.timezone || context.timezone || '',
      data_source: Object.keys(telemetry).length ? 'WIaaS live regional telemetry' : 'WIaaS selected-region context',
      backend_status: Object.keys(telemetry).length ? 'ONLINE' : 'DATA_PENDING',
      system_status: raw.system_status || 'CONTEXT_READY',
      request_kind: raw.request_kind || 'standard_query',
      execution_mode: raw.execution_mode || 'efficient',
      response_style: raw.response_style || 'brief',
      max_response_words: raw.max_response_words || 140,
      token_strategy: raw.token_strategy || 'deterministic_and_cached_first',
      session_id: raw.session_id || '',
      turn_index: Number(raw.turn_index) || 1,
      repeated_question_count: Number(raw.repeated_question_count) || 0,
      response_variant: Number(raw.response_variant) || 0,
      recent_user_messages: Array.isArray(raw.recent_user_messages) ? raw.recent_user_messages.slice(-5) : [],
      user_query: String(raw.user_query || raw.chatInput || raw.message || ''),
    },
    forecast_7d: {
      max_temps_c: Array.isArray(forecast7d.max_temps_c) ? forecast7d.max_temps_c : [],
      min_temps_c: Array.isArray(forecast7d.min_temps_c) ? forecast7d.min_temps_c : [],
      precipitation_sums_mm: Array.isArray(forecast7d.precipitation_sums_mm) ? forecast7d.precipitation_sums_mm : [],
      rain_prob_max_pct: Array.isArray(forecast7d.rain_prob_max_pct) ? forecast7d.rain_prob_max_pct : [],
    },
    physics_metrics: {
      vapor_pressure_deficit_kpa: vpd,
      evaporation_loss_percent: evaporationLoss,
      heat_index_celsius: heatIndex,
      wet_bulb_celsius: climate.wet_bulb_celsius ?? null,
      grid_demand_surge_percent: gridSurge,
      thermal_overhead_percent: thermalOverhead,
    },
    calculated_risk_state: { initial_risk_level: riskLevel, mission_criticality_score: missionScore },
    grid_outlook: {
      max_blackout_risk_pct: summary.max_blackout_risk_pct ?? null,
      peak_surge_hour: summary.peak_surge_hour ?? null,
      grid_status: summary.grid_status ?? null,
      action_required: trigger.action_required ?? false,
      recommended_mitigation: trigger.recommended_mitigation ?? 'NONE',
    },
    telemetry: {
      temperature_celsius: telemetry.temperature_celsius ?? null,
      humidity_percentage: telemetry.humidity_percentage ?? null,
      wind_speed_kmh: windSpeed,
      wind_direction_degrees: windDir,
    },
    ledger: { ...ledger, water_irrigation_efficiency_pct: irrigationEfficiency, grid_available_capacity_mw: ledger.grid_available_capacity_mw ?? null },
  };

  return {
    ...raw,
    ...state,
    region,
    data_source: state.metadata.data_source,
    backend_status: state.metadata.backend_status,
    risk_level: riskLevel,
    mission_criticality_score: missionScore,
    temperature_celsius: state.telemetry.temperature_celsius,
    humidity_percentage: state.telemetry.humidity_percentage,
    heat_index_celsius: heatIndex,
    vapor_pressure_deficit_kpa: vpd,
    grid_demand_surge_percent: gridSurge,
    thermal_overhead_percent: thermalOverhead,
    state_vector: JSON.stringify(state),
  };
})() }}

parameters.jsCode:
const j = $input.first().json || {};
function parse(value) { try { return typeof value === 'object' ? value : JSON.parse(value); } catch (e) { return {}; } }
let router = {};
try { router = $('Match Region').first().json || {}; } catch (e) {}
const state = parse(j.state_vector);
const m = state.metadata || {};
const p = state.physics_metrics || {};
const t = state.telemetry || {};
const l = state.ledger || {};
const riskState = state.calculated_risk_state || {};
const region = m.region || j.region || router.matched_region_name || '';
const intent = router.intent_type || j.intent_type || 'weather_summary_query';
const field = router.requested_field || j.requested_field || '';
const query = String(m.user_query || j.user_query || j.chatInput || j.original_message || router.user_message || '').toLowerCase();
const responseLanguage = String(j.response_language || router.response_language || m.response_language || 'en').toLowerCase().startsWith('ur') ? 'ur' : 'en';
const channel = router.channel || j.channel || 'chat';

function fmt(value, unit) {
  if (value === null || value === undefined || value === '') return 'Not available';
  const clean = typeof value === 'number' ? Math.round(value * 100) / 100 : value;
  return String(clean) + (unit || '');
}

const temperature = t.temperature_celsius ?? j.temperature_celsius;
const humidity = t.humidity_percentage ?? j.humidity_percentage;
const heatIndex = p.heat_index_celsius ?? j.heat_index_celsius;
const vpd = p.vapor_pressure_deficit_kpa ?? j.vapor_pressure_deficit_kpa;
const wind = t.wind_speed_kmh ?? j.wind_speed_kmh;
const gridSurge = p.grid_demand_surge_percent ?? j.grid_demand_surge_percent;
const thermal = p.thermal_overhead_percent ?? j.thermal_overhead_percent;
const evaporation = p.evaporation_loss_percent ?? j.evaporation_loss_percent;
const irrigation = l.water_irrigation_efficiency_pct ?? j.water_irrigation_efficiency_pct;
const capacity = l.grid_available_capacity_mw ?? j.grid_available_capacity_mw;
const risk = riskState.initial_risk_level ?? j.risk_level ?? 'MEDIUM';
const score = riskState.mission_criticality_score ?? j.mission_criticality_score ?? 65;

// GUARD: If region is missing, Null, or undefined
const isNullRegion = !region || ["null", "none", "undefined", "n/a", "selected asian region"].includes(String(region).toLowerCase().trim());
if (isNullRegion) {
  const noRegionEn = "Please select a region from the Asia map (or specify an Asian city or country like Karachi, Multan, Islamabad, Tokyo, Beijing, Delhi, etc.), and I will provide you with the live intelligence and details.";
  const noRegionUr = "براہ کرم ایشیا کے نقشے سے کوئی علاقہ منتخب کریں (یا کسی ایشیائی شہر یا ملک جیسے کراچی، ملتان، اسلام آباد، ٹوکیو، بیجنگ، دہلی کا نام بتائیں)، تاکہ میں آپ کو لائیو معلومات فراہم کر سکوں۔";
  const output = responseLanguage === 'ur' ? noRegionUr : noRegionEn;
  return [{ json: { ...j, output, chat_response: output, final_response: output, speech_en: noRegionEn, speech_ur: noRegionUr, channel } }];
}

let englishOutput = "";
let urduOutput = "";
const rLower = region.toLowerCase();

// Check if query is farmer/agriculture related
const isFarmerQuery = intent === 'farmer_query' || intent === 'farmer_action_query' || intent === 'crop_building_query' || intent === 'scouting_window_query' || intent === 'crop_stress_query' || query.includes('farmer') || query.includes('crop') || query.includes('corps');

// =========================================================================
// SCENARIO 1: RAIN / DOWNPOUR / WATERLOGGING DURING FARMING
// =========================================================================
if (isFarmerQuery && (query.includes('rain') || query.includes('raining') || query.includes('downpour') || query.includes('waterlogging') || query.includes('standing water') || query.includes('flood'))) {
  if (rLower.includes('multan')) {
    englishOutput = `**Emergency Rain & Inundation Directives for Farmers in Multan (Cotton & Mango Belt)**

1. **Halt All Irrigation Immediately:** Shut off electric tube-wells and canal turnouts right away to prevent root-zone over-saturation.
2. **Open Drainage Furrows & Siphon Standing Water:** Cut bund spillways to drain excess water from flat basins into lower-lying drains. Cotton is extremely sensitive to waterlogging (standing water exceeding 12–24 hours causes root asphyxiation, yellowing, and square drop).
3. **Suspend Chemical & Foliar Sprays:** Do not apply foliar sprays or granular urea on wet soil. Saturated roots cannot absorb nutrients, and foliar sprays will wash off.
4. **Post-Rain Fungal & Disease Scouting:** As soon as rain subsides, inspect mango orchards for anthracnose and cotton fields for fungal root rot. Apply protective systemic fungicide as soon as leaves dry.
5. **Soil Aeration (Choor/Hoeing):** Once the field reaches 'wattar' condition (workable soil moisture), perform shallow hoeing between rows to break soil crust, restore aeration, and prevent salt capillary rise.`;
    urduOutput = `**ملتان کے کسانوں کے لیے بارش اور نکاسی آب کے ہنگامی احکامات (کپاس اور آم)**

1. **آبپاشی فوری بند کریں:** تمام ٹیوب ویل اور نہری نکے فوری بند کر دیں۔ کپاس میں 12 سے 24 گھنٹے سے زیادہ کھڑا پانی جڑوں کا دم گھٹنے اور ٹینڈے گرنے کا سبب بنتا ہے۔
2. **پانی کے فوری نکاس کے راستے کھولیں:** کھیتوں کی وٹیں کاٹ کر کھڑا پانی قریبی کھالوں یا نشیبی راستوں میں نکالیں۔
3. **کھاد اور اسپرے کا فوری تعطل:** گیلے کھیت میں یوریا یا کسی بھی کیمیکل کا اسپرے نہ کریں۔ بارش میں یہ بہہ کر ضائع ہو جاتا ہے۔
4. **بارش کے بعد فنگس اور بیماریوں سے بچاؤ:** بارش رکتے ہی آم کے باغات میں اینتھراکنوز اور کپاس میں فنگل بیماریوں کی جانچ کریں اور پتے سوکھتے ہی حفاظتی فنجی سائیڈ اسپرے کریں۔
5. **وتر آنے پر گوڈی (Choor):** جب زمین وتر حالت میں آئے تو پٹڑیوں کے درمیان ہلکی گوڈی کریں تاکہ مٹی کی سخت تہہ ٹوٹے، جڑوں کو ہوا ملے اور پودوں کا تناؤ ختم ہو۔`;
  } else if (rLower.includes('beijing') || rLower.includes('china')) {
    englishOutput = `**Rain & Inundation Directives for Farmers in Beijing & North China Plain (Wheat & Maize Belt)**

1. **Clear Drainage Sluices Immediately:** Inundation exceeding 18 hours in clay-loam soils suffocates summer maize and winter wheat crowns. Ensure all perimeter ditches are free of silt.
2. **Halt Nitrogen Broadcast:** Stop granular fertilizer broadcasting to avoid severe nitrate leaching into groundwater.
3. **Prevent Post-Rain Smut & Blight:** Warm summer rains trigger corn leaf blight and stalk rot. Apply protective carbendazim or mancozeb as soon as sunshine returns.
4. **Inter-Row Cultivation:** Once soil crusts at workable moisture, execute inter-row rotary tilling to aerate compacted soils and preserve topsoil structure.`;
    urduOutput = `**بیجنگ اور شمالی چین کے کسانوں کے لیے بارش اور نکاسی کے احکامات (گندم و مکئی)**

1. **نکاسی نالوں کی صفائی:** مکئی کے کھیت میں 18 گھنٹے سے زیادہ پانی کھڑا رہنے سے جڑوں کو آکسیجن نہیں ملتی۔ پانی فوری نکالیں۔
2. **کھاد کا استعمال روکیں:** گیلے کھیت میں نائٹروجن کھاد زمین میں بہہ کر ضائع ہو جاتی ہے۔
3. **فنگس اور جھلساؤ سے بچاؤ:** بارش کے بعد مکئی میں تنے کے گل سڑاؤ کے خلاف تجویز کردہ اسپرے کریں۔
4. **وتر پر ہل چلائیں:** مٹی سخت ہونے سے بچانے کے لیے وتر آنے پر ہلکی گوڈی کریں۔`;
  } else if (rLower.includes('tokyo') || rLower.includes('japan')) {
    englishOutput = `**Typhoon Rain & Drainage Management for Japan (Kanto Plain)**

1. **Paddy Water Gate Regulation:** Open sluice gates on lowland rice paddies to prevent deep standing water from submerging tillering stalks during sudden downpours.
2. **Greenhouse Drainage Perimeter:** Dig runoff swales around horticultural tunnel greenhouses to prevent basement flooding of delicate berry and hydroponic crops.
3. **Post-Downpour Fungicide Application:** Maritime humidity post-rain spikes above 90%. Spray copper-based bactericides to halt bacterial leaf blight spread.`;
    urduOutput = `**ٹوکیو اور جاپان میں شدید بارش اور طوفان کے دوران کسانوں کے لیے ہدایات**

1. **دھان کے کھیتوں کے نکے کھولیں:** چاول کے پودوں کو زیادہ پانی میں ڈوبنے سے بچانے کے لیے نکاسی کے راستے کھولیں۔
2. **گرین ہاؤسز کا تحفظ:** سبزیوں اور اسٹرابیری کے گرین ہاؤسز کے گرد نالیاں بنائیں تاکہ پانی اندر نہ جائے۔
3. **فنگس کے خلاف اسپرے:** بارش کے فوراً بعد فنگس کش دوا کا اسپرے کریں تاکہ تیز نمی سے بیماریاں نہ پھیلیں۔`;
  } else if (rLower.includes('lahore')) {
    englishOutput = `**Rain & Inundation Management for Farmers in Lahore & Central Punjab (Basmati Belt)**

1. **Regulate Paddy Water Depth:** For Basmati rice, keep standing water depth at 2–3 inches. Drain excess rainwater exceeding 4 inches to prevent young seedling submergence and stem rot.
2. **Evacuate Water from Vegetable Fields:** Ridge-grown vegetables and fodder plots must be evacuated of standing water within 12 hours.
3. **Suspend Nitrogen Top-Dressing:** Do not apply broadcast urea until standing water is drained to prevent massive denitrification losses.
4. **Stem Borer & Leaf Blast Vigilance:** High humidity and wet foliage favor blast lesions. Apply recommended systemic fungicides immediately as foliage dries.`;
    urduOutput = `**لاہور اور سینٹرل پنجاب میں بارش کے دوران کسانوں کے لیے رہنمائی (باسمتی چاول و سبزیات)**

1. **دھان کے کھیت میں پانی کنٹرول کریں:** باسمتی کے لیے 2 سے 3 انچ پانی کافی ہے۔ 4 انچ سے زیادہ اضافی بارش کا پانی نکال دیں تاکہ پنیری نہ ڈوبے۔
2. **سبزیوں کے کھیتوں سے نکاسی:** سبزیوں اور چارے کے کھیتوں سے پانی فوری نکالیں تاکہ جڑوں کا گل سڑاؤ نہ ہو۔
3. **یوریا کھاد روک دیں:** کھڑے پانی میں کھاد نہ ڈالیں تاکہ نائٹروجن بہہ کر ضائع نہ ہو۔
4. **بیماریوں کی بروقت روک تھام:** بارش کے بعد چاول میں پتوں کے جھلساؤ اور تنے کی سنڈی کی فوری نگرانی کریں اور تجویز کردہ فنجی سائیڈ استعمال کریں۔`;
  } else if (rLower.includes('karachi')) {
    englishOutput = `**Rain & Drainage Directives for Coastal Sindh & Karachi (Malir Basin)**

1. **Open Coastal Raised-Bed Spillways:** Malir and Gadap vegetable beds are highly prone to rapid root rot under warm coastal rains. Ensure all furrow drains are unobstructed.
2. **Prevent Fruit Splitting & Rot:** In papaya and tomato crops, ensure water drains away from stems to prevent collar rot (Phytophthora) and fungal fruit drop.
3. **Immediate Post-Rain Fungicide Coverage:** Coastal maritime humidity post-rain jumps to >85%. Spray systemic metalaxyl-mancozeb as soon as rain halts to suppress downy mildew.`;
    urduOutput = `**کراچی اور کوسٹل سندھ میں بارش کے دوران کسانوں کے لیے لائحہ عمل (ملیر و گڈاپ)**

1. **پٹڑیوں سے پانی کا فوری نکاس:** ملیر کی سبزیوں میں کھڑا پانی چند گھنٹوں میں جڑیں گلا دیتا ہے۔ نکاسی کے نالے فوری کھولیں۔
2. **پپیتے اور ٹماٹر کا تحفظ:** تنے کے قریب پانی کھڑا نہ ہونے دیں تاکہ پھل پھٹنے اور فنگس سے محفوظ رہے۔
3. **بارش کے فوراً بعد فنجی سائیڈ اسپرے:** سمندری نمی بڑھنے سے ڈاؤنئی ملڈیو کا خطرہ ہوتا ہے، اس لیے پتے خشک ہوتے ہی اسپرے کریں۔`;
