parameters.jsCode:
// Preserve the complete incoming webhook payload while normalizing one readable report.
const incoming = $input.first().json || {};
function obj(v) { try { return v && typeof v === 'object' && !Array.isArray(v) ? v : JSON.parse(v); } catch (e) { return {}; } }
function readable(v) {
  if (v === null || v === undefined || typeof v === 'object') return '';
  const s = String(v).replace(/\x60\x60\x60(?:json)?|\x60\x60\x60/gi, '').trim();
  if (!s) return '';
  try { if (JSON.parse(s) && typeof JSON.parse(s) === 'object') return ''; } catch (e) {}
  return s.replace(/\*\*/g, '').replace(/^[-#]+\s*/gm, '').replace(/\s+/g, ' ').trim();
}
const state = obj(incoming.state_vector);
const metadata = state.metadata || {};
const physics = state.physics_metrics || {};
const telemetry = incoming.telemetry || state.telemetry || {};
const climate_matrix = incoming.climate_matrix || state.climate_matrix || {};
const ledger = incoming.ledger || state.ledger || {};
const riskState = state.calculated_risk_state || {};
const pick = (...values) => values.find((v) => v !== undefined && v !== null && v !== '');
const region_key = pick(incoming.region_key, metadata.region_key, incoming.region_context?.key, '');
const region_name = pick(incoming.region_name, metadata.region_name, metadata.region, incoming.region, incoming.region_context?.name, 'the selected region');
const region_context = pick(incoming.region_context, state.region_context, {});
const risk_level = pick(incoming.risk_level, riskState.initial_risk_level, 'n/a');
const mission_criticality_score = pick(incoming.mission_criticality_score, riskState.mission_criticality_score, 'n/a');
const research = readable(pick(incoming.research_summary, incoming.research, incoming.regional_summary));
const agriculture = readable(incoming.agriculture_impact);
const grid = readable(incoming.grid_impact);
const logistics = readable(incoming.logistics_impact);
const suppliedReport = readable(pick(incoming.report, incoming.readable_report));
const actions = Array.isArray(incoming.next_actions) ? incoming.next_actions : [];
const actionText = actions.map((a, i) => {
  const title = readable(a?.title || a?.action) || 'Action';
  const detail = readable(a?.description || a?.reason);
  return (i + 1) + '. ' + title + (detail ? ': ' + detail : '');
}).join('\n');
const metrics = [
  'Temperature: ' + pick(telemetry.temperature_celsius, 'n/a') + ' C',
  'Humidity: ' + pick(telemetry.humidity_percentage, 'n/a') + ' %',
  'Heat Index: ' + pick(physics.heat_index_celsius, 'n/a') + ' C',
  'VPD: ' + pick(physics.vapor_pressure_deficit_kpa, 'n/a') + ' kPa',
  'Grid Demand Surge: ' + pick(physics.grid_demand_surge_percent, 'n/a') + ' %'
].join('\n');
const sections = [
  suppliedReport,
  'Region: ' + region_name + '\nRisk Level: ' + risk_level + '\nMission Criticality Score: ' + mission_criticality_score,
  'Live Metrics:\n' + metrics,
  research && 'Research Summary:\n' + research,
  agriculture && 'Agriculture Impact:\n' + agriculture,
  grid && 'Grid Impact:\n' + grid,
  logistics && 'Logistics Impact:\n' + logistics,
  actionText && 'Next Actions:\n' + actionText
].filter(Boolean);
const chat_message = sections.join('\n\n') || 'No readable CrisisLens report was generated.';
let channel = pick(incoming.channel, 'chat');
try { channel = $('Match Region').first().json.channel || channel; } catch (e) {}
return [{ json: {
  ...incoming,
  webhook: incoming.webhook && typeof incoming.webhook === 'object' ? { ...incoming.webhook, body: incoming.webhook.body } : incoming.webhook,
  region_key, region_name, region_context, telemetry, climate_matrix, ledger, risk_level, mission_criticality_score,
  chat_message, output: chat_message, final_response: chat_message, channel
} }];

const j = $input.first().json;

let src = {};
try { src = $("Save Logistics Output").first().json || {}; } catch (e) {}

function pjObj(v){ try{ return typeof v === "object" ? v : JSON.parse(v); }catch(e){ return {}; } }
function pjArr(v){ try{ const a = typeof v === "object" ? v : JSON.parse(v); return Array.isArray(a) ? a : []; }catch(e){ return []; } }

function clean(t){
  if(!t) return "";
  let s = String(t).replace(/```[a-z]*|```/gi, "").replace(/\*\*/g, "").replace(/^[-#]+\s*/gm, "");
  const bad = /^(the user|constraints?|i need to|i must|i should|let'?s|here('|)s (the|a|your)|note:|reasoning:|thinking:|analysis:|plan:|system prompt|workflow|internal|agent prompt|as an ai|okay,|sure,)/i;
  return s.split(/\n/).map(l => l.trim()).filter(l => l && !bad.test(l)).join(" ").replace(/[ \t]+/g, " ").trim();
}

function trimIncomplete(t){
  if(!t) return t;
  let s = String(t).trim();
  if(/[.!?)"\u201d]$/.test(s)) return s;
  const idx = Math.max(s.lastIndexOf(". "), s.lastIndexOf("! "), s.lastIndexOf("? "));
  if(idx > 20){ return s.slice(0, idx + 1).trim(); }
  return s;
}

function capWords(value, maxWords){
  const original = String(value || '').trim();
  const matches = [...original.matchAll(/\S+/g)];
  if(matches.length <= maxWords) return original;
  const last = matches[Math.max(0, maxWords - 1)];
  const candidate = original.slice(0, last.index + last[0].length).trim();
  const endings = [...candidate.matchAll(/[.!?](?=\s|$)/g)];
  if(endings.length && endings[endings.length - 1].index > 20){
    return candidate.slice(0, endings[endings.length - 1].index + 1).trim();
  }
  return candidate.replace(/[,:;(\[]+$/, '').trim() + '…';
}

function num(v){
  if(v === null || v === undefined || v === "") return null;
  if(typeof v === "number") return Math.round(v * 10000) / 10000;
  const n = Number(v);
  return isNaN(n) ? v : Math.round(n * 10000) / 10000;
}
function fmt(v){ const n = num(v); return (n === null) ? "n/a" : String(n); }

const sv = pjObj(src.state_vector || j.state_vector);
const m = sv.metadata || {}, p = sv.physics_metrics || {}, t = sv.telemetry || {}, l = sv.ledger || {}, r = sv.calculated_risk_state || {};

const region = m.region || src.region || j.region || "the selected region";
const dataSource = m.data_source || src.data_source || "n/a";
const backendStatus = m.backend_status || src.backend_status || "n/a";
const riskLevel = r.initial_risk_level || src.risk_level || "n/a";
const missionScore = (r.mission_criticality_score !== undefined && r.mission_criticality_score !== null) ? r.mission_criticality_score : src.mission_criticality_score;

const rawResearch = clean(src.research_summary);
const researchUnavailable = /^(no research summary(?: generated)?|research summary unavailable|n\/?a\.?)$/i.test(rawResearch);
const researchLooksLikeMetadata = /(?:comprehensive specialist report|^\s*region:|timezone:|coordinates:)/i.test(rawResearch) || /[([][^)\]]*$/.test(rawResearch);
const researchIncomplete = rawResearch && !/[.!?]["”]?$/.test(rawResearch);
const research = (!researchUnavailable && !researchLooksLikeMetadata && !researchIncomplete && capWords(rawResearch, 120)) || `The selected region is currently assessed at ${riskLevel} operational risk with a mission criticality score of ${fmt(missionScore)}. The research layer combines the live temperature (${fmt(t.temperature_celsius)}°C), humidity (${fmt(t.humidity_percentage)}%), heat index (${fmt(p.heat_index_celsius)}°C), VPD (${fmt(p.vapor_pressure_deficit_kpa)} kPa), grid-demand surge (${fmt(p.grid_demand_surge_percent)}%), and thermal-overhead (${fmt(p.thermal_overhead_percent)}%) signals. Use this evidence as a current situational baseline and refresh the analysis when conditions change.`;
const agri = capWords(clean(src.agriculture_impact), 110) || "See live metrics for current agricultural conditions.";
const grid = capWords(clean(src.grid_impact), 110) || "See live metrics for current grid conditions.";

const go = sv.grid_outlook || {};
let gridOutlookLine = "";
const hasOutlook = (go.peak_surge_hour) || (go.max_blackout_risk_pct !== null && go.max_blackout_risk_pct !== undefined);
if (hasOutlook) {
  const risk = (go.max_blackout_risk_pct === null || go.max_blackout_risk_pct === undefined) ? "n/a" : go.max_blackout_risk_pct + "%";
  const act = go.action_required ? ("Action required: " + (go.recommended_mitigation || "review mitigation") + ".") : "No mitigation action required.";
  gridOutlookLine = `\nGrid Outlook: Peak blackout risk ${risk} at ${go.peak_surge_hour || "n/a"} (grid status ${go.grid_status || "n/a"}). ${act}`;
}

let logisticsRaw = src.logistics_impact || "";
let recoveredActions = null;
let logisticsText = logisticsRaw;
const ls = String(logisticsRaw).trim();
if (ls.startsWith("{") && ls.indexOf("logistics_impact") !== -1) {
  try {
    const parsed = JSON.parse(ls);
    logisticsText = parsed.logistics_impact || parsed.logisticsImpact || logisticsText;
    if (Array.isArray(parsed.next_actions) && parsed.next_actions.length) recoveredActions = parsed.next_actions;
    else if (Array.isArray(parsed.nextActions) && parsed.nextActions.length) recoveredActions = parsed.nextActions;
  } catch (e) {
    const mm = ls.match(/"logistics_impact"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    if (mm) { try { logisticsText = JSON.parse('"' + mm[1] + '"'); } catch (_) { logisticsText = mm[1]; } }
  }
}
const logistics = capWords(clean(logisticsText), 70) || "See live metrics for current logistics readiness.";

let actions = pjArr(src.next_actions);
const defaults = [
  { title: "Monitor heat exposure", description: "Track heat index and VPD during peak hours." },
  { title: "Maintain irrigation readiness", description: "Use evaporation and crop-stress indicators to guide irrigation timing." },
  { title: "Continue grid and logistics monitoring", description: "Watch grid demand surge, thermal overhead, and essential movement." }
];
function isDefaultSet(arr){
  if(!arr.length) return true;
  const first = String((arr[0] && (arr[0].title || arr[0].action)) || "").toLowerCase();
  return first === "monitor heat exposure";
}
if (recoveredActions && recoveredActions.length && isDefaultSet(actions)) {
  actions = recoveredActions;
}
if (!actions.length) actions = [];
while(actions.length < 3){ actions.push(defaults[actions.length]); }
actions = actions.slice(0, 3);
const actionsText = actions.map((a, i) => {
  const title = String((a && (a.title || a.action)) || "Action").trim();
  const desc = String((a && (a.description || a.reason)) || "").trim();
  return `${i + 1}. ${desc ? title + ": " + desc : title}`;
}).join("\n");

const metrics = [
  `- Temperature: ${fmt(t.temperature_celsius)}\u00B0C`,
  `- Humidity: ${fmt(t.humidity_percentage)}%`,
  `- Heat Index: ${fmt(p.heat_index_celsius)}\u00B0C`,
  `- VPD: ${fmt(p.vapor_pressure_deficit_kpa)} kPa`,
  `- Evaporation Loss: ${fmt(p.evaporation_loss_percent)}%`,
  `- Irrigation Efficiency: ${fmt(l.water_irrigation_efficiency_pct)}%`,
  `- Grid Available Capacity: ${fmt(l.grid_available_capacity_mw)} MW`,
  `- Grid Demand Surge: ${fmt(p.grid_demand_surge_percent)}%`,
  `- Thermal Overhead: ${fmt(p.thermal_overhead_percent)}%`,
  `- Wind Speed: ${fmt(t.wind_speed_kmh)} km/h`
].join("\n");

const report = `WIaaS Analysis Complete

Region: ${region}
Data Source: ${dataSource}
Backend Status: ${backendStatus}
Risk Level: ${riskLevel}
Mission Criticality Score: ${fmt(missionScore)}

Research Summary:
${research}

Live Metrics:
${metrics}

Agriculture Impact:
${agri}

Grid Impact:
${grid}${gridOutlookLine}

Logistics Impact:
${logistics}

Next Actions:
${actionsText}`;

let channel = "chat"; try{ channel = $("Compile For Report").first().json.channel || "chat"; }catch(e){}
const requestedLimit = Number(m.max_response_words || 650);
const boundedReport = capWords(report, Number.isFinite(requestedLimit) ? Math.max(200, Math.min(650, requestedLimit)) : 650);
return [{ json: { output: boundedReport, chat_response: boundedReport, final_response: boundedReport, channel } }];

