const CRISIS      = ["anomaly","polygon","crisis","threat","osint","emergency","drought","heatwave","disaster","evacuation","hazard","triage"];
const FAQ_DEF     = ["what is wiaas","whats wiaas","how does it work","how does wiaas work","what can you do","what do you do","who are you","what are you","explain wiaas","how do i use"];
const MATH_VERBS  = ["calculate","compute","convert","formula","equation","solve"];
const WIAAS       = [
  "run analysis","run wiaas","wiaas analysis","wiaas","risk level","risk report","generate report","current status","current conditions",
  "irrigation","grid demand","agriculture impact","grid impact","logistics impact","research summary","heat stress","weather summary",
