  field = "heat_index";
} else if (hasAny(["vpd", "vapor pressure"])) {
  intentType = "single_metric_query";
  field = "vpd";
} else if (hasAny(["wind speed", "wind"])) {
  intentType = "single_metric_query";
  field = "wind_speed";
} else if (hasAny(["risk level", "current risk", "mission criticality"])) {
  intentType = "risk_only_query";
} else if (hasAny(["agriculture", "agri"])) {
  intentType = "section_query";
  field = "agriculture";
} else if (hasAny(["grid", "power"])) {
  intentType = "section_query";
  field = "grid";
} else if (hasAny(["logistics", "supply", "transport"])) {
  intentType = "section_query";
  field = "logistics";
} else if (hasAny(["weather", "conditions", "summarize"])) {
  intentType = "weather_summary_query";
} else if (isGreeting) {
  intentType = "faq_query";
}

const analysisIntents = new Set([
  "single_metric_query",
  "weather_summary_query",
  "section_query",
  "risk_only_query",
  "full_report_query",
  "irrigation_query",
  "cargo_query",
  "adaptation_query",
  "flood_query",
  "crop_stress_query",
  "evaporation_query",
  "grid_capacity_query",
  "demand_surge_query",
  "grid_risk_query",
  "farmer_query",
  "farmer_action_query",
  "crop_building_query",
  "scouting_window_query"
]);

let directResponse = "";
if (asksWhichRegions) {
  directResponse = "WIaaS covers Asian territories across South, East, Central, and Western Asia. Tell me any city or country (e.g. Karachi, Islamabad, Multan, Tokyo, Beijing, Delhi, Riyadh) and I will provide you with live environmental intelligence.";
} else if (isGreeting) {
  directResponse = "Hi! I am the WIaaS Weather Intelligence assistant. Tell me an Asian region or ask about temperature, heat index, humidity, crop stress, irrigation timing, power grid risk, logistics safety, or request a full WIaaS analysis.";
}

// Guard: If it's an analysis intent but NO region is selected or found in query
let wiaasMode = asksWhichRegions ? "region_list" : (analysisIntents.has(intentType) ? "analysis" : "faq");
let regionStatus = hasRegion ? "resolved" : "missing";

if (analysisIntents.has(intentType) && !hasRegion) {
  regionStatus = "missing";
  directResponse = "Please select a region from the Asia map (or specify an Asian city or country like Karachi, Multan, Islamabad, Tokyo, etc.), and I will provide you with the live intelligence and details.";
}

return [
  {
    json: {
      ...payload,
      user_message: userMessage,
      channel,
      session_id: sessionId,
      intent_type: intentType,
      requested_field: field,
      region_key: effectiveKey,
      region_name: effectiveName,
      region_context: suppliedContext,
      wiaas_mode: wiaasMode,
      region_status: regionStatus,
      wiaas_focus: field || intentType,
      requested_region: effectiveName || userMessage,
      direct_response: directResponse
    }
  }
];
